ule":{"name":"UPPERMOST_WHATSAPP_CART_RECOVERY_V1","description":"STAGING DRAFT ONLY. Cart inactivity >=1h and <24h; no checkout or projected purchase; 15-minute audience polling when dispatcher is available. Not activation-ready: verify content, lifecycle suppression and scheduler.","status":"DRAFT","trigger_type":"SCHEDULE","trigger_event_type":null,"cron_expression":"*/15 * * * *","timezone":"Asia/Kolkata","condition_config":{"all":[{"field":"whatsapp_marketing_allowed","op":"eq","value":true},{"field":"cart_value_paise","op":"gt","value":0},{"field":"cart_checkout_started","op":"eq","value":false},{"field":"cart_converted","op":"eq","value":false},{"field":"last_cart_activity_at","op":"hours_since_gte","value":1},{"none":[{"field":"last_cart_activity_at","op":"hours_since_gte","value":24}]}]},"action_config":{"templates":{},"variables":{},"abandoned_cart":true},"priority":0,"frequency_cap":{"weekly":1,"cooldown_hours":168},"quiet_hours":{"start":21,"end":9},"valid_from":null,"valid_until":null}},{"template_logical_key":"UPPERMOST_WHATSAPP_SHIPPING_UPDATE_V1","template":{"logical_key":"UPPERMOST_WHATSAPP_SHIPPING_UPDATE_V1","name":"UPPERMOST_WHATSAPP_SHIPPING_UPDATE_V1","channel":"WHATSAPP","category":"TRANSACTIONAL","subject":"","html_content":"","text_content":"Hello {{1}}, the shipping status for Uppermost order {{2}} is {{3}}.","structured_content":{"components":[{"type":"BODY","text":"Hello {{1}}, the shipping status for Uppermost order {{2}} is {{3}}.","example":{"body_text":[["Sample Customer","UM-TEST-001","In transit"]]}}]},"parameter_schema":{"required":["name","order_number","shipment_status"],"body_parameters":["name","order_number","shipment_status"]},"change_reason":"Staging draft; business copy review and Meta approval required."},"rule":{"name":"UPPERMOST_WHATSAPP_SHIPPING_UPDATE_V1","description":"STAGING DRAFT ONLY. Explicit shipping-status allowlist; provider variant and event-order checks remain activation blockers. Not activation-ready: verify content, lifecycle suppression and scheduler.","status":"DRAFT","trigger_type":"EVENT","trigger_event_type":"commerce.shipment.changed","cron_expression":null,"timezone":"Asia/Kolkata","condition_config":{"all":[{"field":"last_shipment_status","op":"in","value":["ORDER_SHIPPED","IN_TRANSIT","OUT_FOR_DELIVERY","SHIPPED","Shipped","IN TRANSIT","In Transit","OUT FOR DELIVERY","Out For Delivery"]}]},"action_config":{"templates":{},"variables":{},"abandoned_cart":false},"priority":0,"frequency_cap":{"weekly":3,"cooldown_hours":24},"quiet_hours":{"start":0,"end":0},"valid_from":null,"valid_until":null}},{"template_logical_key":"UPPERMOST_WHATSAPP_ORDER_CONFIRMATION_V1","template":{"logical_key":"UPPERMOST_WHATSAPP_ORDER_CONFIRMATION_V1","name":"UPPERMOST_WHATSAPP_ORDER_CONFIRMATION_V1","channel":"WHATSAPP","category":"TRANSACTIONAL","subject":"","html_content":"","text_content":"Hello {{1}}, payment for Uppermost order {{2}} is confirmed.","structured_content":{"components":[{"type":"BODY","text":"Hello {{1}}, payment for Uppermost order {{2}} is confirmed.","example":{"body_text":[["Sample Customer","UM-TEST-001"]]}}]},"parameter_schema":{"required":["name","order_number"],"body_parameters":["name","order_number"]},"change_reason":"Staging draft; business copy review and Meta approval required."},"rule":{"name":"UPPERMOST_WHATSAPP_ORDER_CONFIRMATION_V1","description":"STAGING DRAFT ONLY. Authoritative order confirmation event; requires order-specific content resolution. Not activation-ready: verify content, lifecycle suppression and scheduler.","status":"DRAFT","trigger_type":"EVENT","trigger_event_type":"commerce.order.confirmed","cron_expression":null,"timezone":"Asia/Kolkata","condition_config":{"all":[{"field":"order_count","op":"gte","value":1}]},"action_config":{"templates":{},"variables":{},"abandoned_cart":false},"priority":0,"frequency_cap":{"weekly":3,"cooldown_hours":24},"quiet_hours":{"start":0,"end":0},"valid_from":null,"valid_until":null}},{"template_logical_key":"UPPERMOST_WHATSAPP_DELIVERY_CONFIRMATION_V1","template":{"logical_key":"UPPERMOST_WHATSAPP_DELIVERY_CONFIRMATION_V1","name":"UPPERMOST_WHATSAPP_DELIVERY_CONFIRMATION_V1","channel":"WHATSAPP","category":"TRANSACTIONAL","subject":"","html_content":"","text_content":"Hello {{1}}, Uppermost order {{2}} has been delivered.","structured_content":{"components":[{"type":"BODY","text":"Hello {{1}}, Uppermost order {{2}} has been delivered.","example":{"body_text":[["Sample Customer","UM-TEST-001"]]}}]},"parameter_schema":{"required":["name","order_number"],"body_parameters":["name","order_number"]},"change_reason":"Staging draft; business copy review and Meta approval required."},"rule":{"name":"UPPERMOST_WHATSAPP_DELIVERY_CONFIRMATION_V1","description":"STAGING DRAFT ONLY. Explicit Delivered status allowlist; exact shipment correlation remains an activation blocker. Not activation-ready: verify content, lifecycle suppression and scheduler.","status":"DRAFT","trigger_type":"EVENT","trigger_event_type":"commerce.shipment.changed","cron_expression":null,"timezone":"Asia/Kolkata","condition_config":{"all":[{"field":"last_shipment_status","op":"in","value":["DELIVERED","Delivered","delivered"]}]},"action_config":{"templates":{},"variables":{},"abandoned_cart":false},"priority":0,"frequency_cap":{"weekly":3,"cooldown_hours":24},"quiet_hours":{"start":0,"end":0},"valid_from":null,"valid_until":null}}]$whatsapp_config$::jsonb) loop
  select v.id into version_id from public.communication_template_versions v join public.communication_templates t on t.id=v.template_id
   where t.logical_key=item->>'template_logical_key' and v.channel='WHATSAPP' order by v.version desc limit 1;
  if version_id is null then
   if item->'template' is null then raise exception 'EXISTING_WELCOME_TEMPLATE_REQUIRED';end if;
   version_id:=public.comm_create_template_version(item->'template',null);
  end if;
  -- Map newly created draft artifacts; approval always remains provider-owned.
  if item ? 'template' then
   update public.communication_template_provider_artifacts a
    set provider_template_name=lower(item->>'template_logical_key'),provider_language='en',sync_mode='PROVIDER_TEMPLATE'
    where a.template_version_id=version_id and a.provider_status='DRAFT'
    and exists(select 1 from public.communication_template_versions v where v.id=version_id and v.status='DRAFT');
  end if;
  rule_data:=item->'rule';
  if not exists(select 1 from public.communication_rules where name=rule_data->>'name') then
   insert into public.communication_rules(name,description,status,trigger_type,trigger_event_type,cron_expression,timezone,condition_config,action_config,channel_strategy,priority,frequency_cap,quiet_hours,next_run_at)
    values(rule_data->>'name',coalesce(rule_data->>'description',''),'DRAFT',rule_data->>'trigger_type',rule_data->>'trigger_event_type',rule_data->>'cron_expression',rule_data->>'timezone',
     rule_data->'condition_config',jsonb_set(rule_data->'action_config','{templates}',jsonb_build_object('WHATSAPP',version_id)),'["WHATSAPP"]'::jsonb,
     coalesce((rule_data->>'priority')::integer,0),rule_data->'frequency_cap',rule_data->'quiet_hours',null);
  end if;
 end loop;
end $prepare_whatsapp$;
